58		}
59		if cert != nil || dup {
60			t.Fatalf("保存失败不能返回已录入或重复证书：cert=%v dup=%v", cert, dup)
61		}
62		if IsValidation(err) || IsConflict(err) || errors.Is(err, ErrNotFound) {
63			t.Fatalf("写盘失败应是保存错误而非业务拒绝：%v", err)
64		}
65	
66		// 继续使用同一台账对象：历史、最近证书与使用资格都与录入前一致。
67		if n := len(l.data.Certificates); n != 0 {
